  <script>
    const monthName = document.getElementById('month-name');
    const calendarDays = document.getElementById('calendar-days');
    const selectedDateText = document.getElementById('selected-date');
    const bookingSummary = document.getElementById('booking-summary');
    const confirmButton = document.getElementById('confirm-booking');
    const toast = document.getElementById('toast');

    const today = new Date();
    const formatter = new Intl.DateTimeFormat('ar-QA', {
      weekday: 'long',
      day: 'numeric',
      month: 'long',
      year: 'numeric'
    });

    let viewDate = new Date(today.getFullYear(), today.getMonth(), 1);
    let selectedDate = null;
    let selectedTime = null;

    function sameDay(first, second) {
      return first.getFullYear() === second.getFullYear() &&
        first.getMonth() === second.getMonth() &&
        first.getDate() === second.getDate();
    }

    function selectDate(date) {
      selectedDate = new Date(date);
      selectedTime = null;
      document.querySelectorAll('.slot').forEach(slot => {
        slot.classList.remove('selected');
        slot.disabled = false;
      });
      updateCalendar();
      updateSummary();
    }

    function updateCalendar() {
      const year = viewDate.getFullYear();
      const month = viewDate.getMonth();

      monthName.textContent = new Intl.DateTimeFormat('ar-QA', {
        month: 'long',
        year: 'numeric'
      }).format(viewDate);

      calendarDays.innerHTML = '';

      const firstDay = new Date(year, month, 1);
      const daysInMonth = new Date(year, month + 1, 0).getDate();
      const saturdayIndex = firstDay.getDay() === 6 ? 0 : firstDay.getDay() + 1;

      for (let i = 0; i < saturdayIndex; i++) {
        const empty = document.createElement('div');
        empty.className = 'day empty';
        empty.setAttribute('aria-hidden', 'true');
        calendarDays.appendChild(empty);
      }

      for (let day = 1; day <= daysInMonth; day++) {
        const date = new Date(year, month, day);
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'day';
        button.textContent = day;
        button.setAttribute('role', 'gridcell');

        if (sameDay(date, today)) {
          button.classList.add('today');
          button.setAttribute('aria-current', 'date');
        }

        if (selectedDate && sameDay(date, selectedDate)) {
          button.classList.add('selected');
          button.setAttribute('aria-selected', 'true');
        }

        const isPast = date < new Date(today.getFullYear(), today.getMonth(), today.getDate());
        const isFriday = date.getDay() === 5;

        if (isPast || isFriday) {
          button.classList.add('unavailable');
          button.disabled = true;
          button.setAttribute('aria-label', date.getDate() + ' غير متاح');
        } else {
          button.setAttribute('aria-label', 'اختر يوم ' + date.getDate());
          button.addEventListener('click', () => selectDate(date));
        }

        calendarDays.appendChild(button);
      }
    }

    function updateSummary() {
      const hasDate = Boolean(selectedDate);
      const hasTime = Boolean(selectedTime);
      confirmButton.disabled = !(hasDate && hasTime);

      if (hasDate && hasTime) {
        const dateLabel = new Intl.DateTimeFormat('ar-QA', {
          weekday: 'long',
          day: 'numeric',
          month: 'long'
        }).format(selectedDate);
        selectedDateText.textContent = dateLabel;
        bookingSummary.textContent = dateLabel + '، ' + selectedTime;
      } else if (hasDate) {
        const dateLabel = new Intl.DateTimeFormat('ar-QA', {
          weekday: 'long',
          day: 'numeric',
          month: 'long'
        }).format(selectedDate);
        selectedDateText.textContent = dateLabel;
        bookingSummary.textContent = 'اختر وقت الموعد';
      } else {
        selectedDateText.textContent = '';
        bookingSummary.textContent = 'اختر التاريخ والوقت';
      }
    }

    document.querySelectorAll('.slot').forEach(slot => {
      slot.addEventListener('click', () => {
        document.querySelectorAll('.slot').forEach(item => item.classList.remove('selected'));
        slot.classList.add('selected');
        selectedTime = slot.dataset.time;
        updateSummary();
      });
    });

    document.getElementById('next-month').addEventListener('click', () => {
      viewDate = new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 1);
      updateCalendar();
    });

    document.getElementById('previous-month').addEventListener('click', () => {
      viewDate = new Date(viewDate.getFullYear(), viewDate.getMonth() - 1, 1);
      updateCalendar();
    });

    confirmButton.addEventListener('click', () => {
      if (!selectedDate || !selectedTime) return;

      toast.textContent = 'تم تأكيد موعدك لدى د. سارة المنصوري.';
      toast.classList.add('show');

      setTimeout(() => {
        toast.classList.remove('show');
      }, 3200);
    });

    document.querySelector('.back-button').addEventListener('click', () => {
      window.history.length > 1 ? window.history.back() : null;
    });

    updateCalendar();
    updateSummary();
  </script>
